import { execFileSync } from 'node:child_process'
import { generateKeyPairSync, randomUUID } from 'node:crypto'
import { chmodSync, existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { pathToFileURL } from 'node:url'
import { parseEnv } from 'node:util'

export const KEYS_FILE = 'supabase/signing_keys.json'
export const STACK_ENV_FILE = 'apps/api/.env.stack'

const ENV_HEADER =
  '# Generated by scripts/supabase-keys.ts for the local Supabase stack; do not edit.'

type JsonWebKeyEntry = Record<string, unknown>

function privateEcJwk() {
  const { privateKey } = generateKeyPairSync('ec', { namedCurve: 'P-256' })
  const { kty, crv, x, y, d } = privateKey.export({ format: 'jwk' })
  return { kty, crv, x, y, d }
}

function stackSigningKey(): JsonWebKeyEntry {
  return {
    ...privateEcJwk(),
    kid: randomUUID(),
    alg: 'ES256',
    use: 'sig',
    key_ops: ['sign', 'verify'],
    ext: true,
  }
}

function writePrivateFile(file: string, content: string) {
  writeFileSync(file, content, { mode: 0o600 })
  chmodSync(file, 0o600)
}

function readStackEnv(cwd: string): Record<string, string> {
  const file = join(cwd, STACK_ENV_FILE)
  if (!existsSync(file)) return {}
  return Object.fromEntries(
    Object.entries(parseEnv(readFileSync(file, 'utf8'))).filter(
      (entry): entry is [string, string] => typeof entry[1] === 'string',
    ),
  )
}

function writeStackEnvFile(cwd: string, values: Record<string, string>) {
  const lines = Object.entries(values).map(([name, value]) => `${name}='${value}'`)
  writePrivateFile(join(cwd, STACK_ENV_FILE), `${[ENV_HEADER, ...lines].join('\n')}\n`)
}

function usableJwtKey(raw: string | undefined): JsonWebKeyEntry | undefined {
  if (!raw) return undefined
  try {
    const key = JSON.parse(raw) as JsonWebKeyEntry
    const complete = ['x', 'y', 'd', 'kid'].every((field) => typeof key[field] === 'string')
    return key.kty === 'EC' && key.crv === 'P-256' && complete ? key : undefined
  } catch {
    return undefined
  }
}

/** The key Better Auth signs with, created in the stack env file when it is not there. */
function ensureJwtKey(cwd: string): JsonWebKeyEntry {
  const env = readStackEnv(cwd)
  const existing = usableJwtKey(env.BETTER_AUTH_JWT_KEY)
  if (existing) return existing
  const key = { ...privateEcJwk(), kid: randomUUID() }
  writeStackEnvFile(cwd, { ...env, BETTER_AUTH_JWT_KEY: JSON.stringify(key) })
  return key
}

/**
 * Writes the keys the local Supabase stack loads: its own signing keys, then the public half of
 * the key Better Auth signs with, so the stack accepts Better Auth's tokens. Returns whether the
 * keys file changed, in which case a running stack must restart to read it.
 */
export function ensureSigningKeys(cwd: string): boolean {
  const file = join(cwd, KEYS_FILE)
  const current = existsSync(file) ? readFileSync(file, 'utf8') : undefined
  const existing = current === undefined ? [] : (JSON.parse(current) as JsonWebKeyEntry[])
  const stackKeys = existing.filter((key) => 'd' in key)
  const { kty, crv, x, y, kid } = ensureJwtKey(cwd)
  const wanted = [
    ...(stackKeys.length > 0 ? stackKeys : [stackSigningKey()]),
    { kty, crv, x, y, kid, alg: 'ES256', use: 'sig', key_ops: ['verify'] },
  ]
  const content = `${JSON.stringify(wanted, null, 2)}\n`
  if (content === current) return false
  writePrivateFile(file, content)
  return true
}

/** Records where the running stack answers, next to the key Better Auth signs with. */
export function writeStackEnv(cwd: string, stack: { API_URL: string; PUBLISHABLE_KEY: string }) {
  writeStackEnvFile(cwd, {
    ...readStackEnv(cwd),
    SUPABASE_URL: stack.API_URL,
    SUPABASE_PUBLISHABLE_KEY: stack.PUBLISHABLE_KEY,
  })
}

function stackStatus(): { API_URL: string; PUBLISHABLE_KEY: string } {
  const output = execFileSync('pnpm', ['exec', 'supabase', 'status', '-o', 'json'], {
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'inherit'],
  })
  const status = JSON.parse(output) as Record<string, unknown>
  const { API_URL, PUBLISHABLE_KEY } = status
  if (
    typeof API_URL !== 'string' ||
    typeof PUBLISHABLE_KEY !== 'string' ||
    !API_URL ||
    !PUBLISHABLE_KEY
  )
    throw new Error('supabase status did not report API_URL and PUBLISHABLE_KEY')
  return { API_URL, PUBLISHABLE_KEY }
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const cwd = process.cwd()
  if (process.argv[2] === 'env') {
    writeStackEnv(cwd, stackStatus())
    console.log(`Wrote ${STACK_ENV_FILE}`)
  } else if (ensureSigningKeys(cwd)) {
    console.log(`Wrote ${KEYS_FILE}; restarting the local stack so it reads the keys`)
    execFileSync('pnpm', ['exec', 'supabase', 'stop'], { stdio: 'inherit' })
  }
}
